import{_ as t,a as o}from"./chunks/on-course-dialog.DTINzmch.js";import{c as n,Q as s,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const i="/assets/set-competitors-dns-dialog.B3MkHTrc.png",y=JSON.parse('{"title":"Safety check: accounting for everyone","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/safety-check.md","filePath":"user/running-the-event/safety-check.md"}'),h={name:"user/running-the-event/safety-check.md"};function l(d,e,c,u,g,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="safety-check-accounting-for-everyone" tabindex="-1">Safety check: accounting for everyone <a class="header-anchor" href="#safety-check-accounting-for-everyone" aria-label="Permalink to &quot;Safety check: accounting for everyone&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators and event organisers making sure nobody is left out on the course at the end of the day.</p><p>The single most important thing timing does for participant safety is answer one question: <strong>is everyone back?</strong> Before search-and-rescue is even a thought, the timing system is the first place anyone looks to see who is still out. This page explains how Manager tracks who is <em>On Course</em>, where to view who still hasn&#39;t returned, how radio punches and card/station downloads move people in and out of <em>On Course</em>, and how to manually correct the picture when the automatic rules get it wrong.</p><blockquote><p>Manager uses the term <em>On Course</em> in the UI. This is the same as <em>In Forest</em> in other event systems. This page uses <strong>On Course</strong> throughout.</p></blockquote><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><p>At the end of the event, you want the <strong>On Course</strong> count to be <strong>zero</strong> — every competitor either has a result (finished, MP, DNF, …) or has been explicitly marked <strong>DNS</strong> because they never started. Anyone still showing <strong>On Course</strong> is, as far as Manager knows, still out on the course.</p><p>A safe wrap-up is therefore:</p><ol><li>Open the <strong>dashboard</strong> and look at the <strong>Competitors</strong> tile. If <strong>On Course</strong> is not zero, click it.</li><li>Work down the <strong>On Course</strong> list — for each person, confirm they&#39;re genuinely still out, have already finished (and just need a download or a manual nudge), or never started (mark them <strong>DNS</strong>).</li><li>Don&#39;t power anything down until that list is empty and you&#39;re confident every remaining name has been physically accounted for by the organisers — not just by the computer.</li></ol><p>The rest of this page explains each step and the things that can mislead you.</p><h2 id="what-on-course-actually-means" tabindex="-1">What &quot;On Course&quot; actually means <a class="header-anchor" href="#what-on-course-actually-means" aria-label="Permalink to &quot;What &quot;On Course&quot; actually means&quot;">​</a></h2><p>A competitor is <strong>On Course</strong> when Manager has evidence they <em>started</em> but no evidence they <em>finished</em>. They get there one of several ways:</p><ul><li><strong>Their allocated start time passed.</strong> A background timer moves anyone with status <em>None</em> and an allocated start time to <strong>On Course</strong> once that start time is reached — even if there&#39;s no radio start punch. This is deliberate: it means people show as out on the course even at events with no start radio.</li><li><strong>A radio start punch arrived.</strong> A <em>start</em> punch from a radio control moves them to <strong>On Course</strong> and sets their start time from the punch.</li><li><strong>Any radio control punch arrived.</strong> A punch at a <em>normal</em> radio control (or a <em>check</em> punch) also moves them to <strong>On Course</strong> — Manager now knows they&#39;re physically out there, even if it missed the start.</li></ul><p>They <em>leave</em> <strong>On Course</strong> when a result appears: a radio <em>finish</em> punch (→ provisional <strong>OK</strong>, see below), or a card download (→ <strong>OK</strong>, <strong>MP</strong> or <strong>DNF</strong>), or a manual status set by you.</p><blockquote><p><strong>Important caveat about the auto-start transition:</strong> because a passed allocated start time alone is enough to flag someone <strong>On Course</strong>, your <strong>On Course</strong> list at the end of the day will normally include every <em>no-show</em> who had a start time but never actually turned up. Those people are not a safety problem — but you can&#39;t tell them apart from genuine missing runners just by looking. Clearing the no-shows (see <a href="#marking-people-on-course-or-not">Marking no-shows as DNS</a>) is what makes the remaining list meaningful.</p></blockquote><p>The full set of rules behind every status is in <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><h2 id="radio-starts-and-finishes" tabindex="-1">Radio starts and finishes <a class="header-anchor" href="#radio-starts-and-finishes" aria-label="Permalink to &quot;Radio starts and finishes&quot;">​</a></h2><p>If your event has radio controls at the start and finish, they do a lot of the safety bookkeeping for you in real time:</p><ul><li>A <strong>radio start and/or check punch</strong> flips a competitor to <strong>On Course</strong> during the start procedure — using a radio on check is ideal for allocated starts and a radio on check and/or start is ideal for punching starts.</li><li>A <strong>radio finish punch</strong> flips them to <strong>OK</strong> the moment they cross the finish — <em>before</em> they reach the download tent. This is the key point for safety: <strong>a radio finish is proof the person has returned</strong>, even though their card hasn&#39;t been read yet.</li></ul><p>So at a well-instrumented event, the <strong>On Course</strong> count tracks the real field closely all day, and the dashboard graph of &quot;On Course over time&quot; rises through the start window and falls as people finish.</p><p>What radios <em>don&#39;t</em> guarantee:</p><ul><li><strong>Not every event has start/finish radios</strong>, and not every control is a radio control. Where there&#39;s no radio coverage, people only move to <strong>On Course</strong> via the allocated-start timer, and only leave it when their card is downloaded. Plan your safety check around what&#39;s actually instrumented.</li><li><strong>Radio punches are not 100%</strong> (out of battery, out of range, or other anomoly). As an extra precaution, also download the start/check/finish units <a href="#reading-sportident-stations">station memory</a> to confirm.</li></ul><h4 id="recommended-start-finish-hardware" tabindex="-1">Recommended start / finish hardware <a class="header-anchor" href="#recommended-start-finish-hardware" aria-label="Permalink to &quot;Recommended start / finish hardware&quot;">​</a></h4><p>How you configure the start, finish and check units has a direct bearing on how reliable your safety picture is.</p><ul><li><strong>Use SRR units (e.g. BSF8-SRR or BSF9-SRR) for the start, finish and check.</strong> These capture <em>every</em> punch — both manual (contact) and contactless (SIAC &quot;air&quot;) — and, being radio-reporting units, broadcast them to Manager via a meshO Control as radio punches as they happen. That keeps the live <strong>On Course</strong> count accurate without waiting for downloads.</li><li><strong>Don&#39;t make the start a Beacon Start — require a punch.</strong> Contactless &quot;air&quot; punching is very confusing for competitors, so it should <strong>not</strong> be used for the start: a beacon start fires when the competitor is in proximity instead of a deliberate action.</li><li><strong>A Beacon Finish is fine.</strong> Air punching at the finish is common and convenient. With an SRR finish unit you&#39;ll get radio finish punches for both SIAC (air) and manual punches, so contactless runners still flip out of <strong>On Course</strong> the moment they cross the line.</li></ul><p>In short: <strong>contact punch at the start, beacon allowed at the finish</strong> so nothing is lost whichever way a runner punches. Requiring a manual start and/or check punch makes <a href="#reading-sportident-stations">reading the station backups</a> definitive - all competitors are recorded. Note that SIAC punches are never recorded by the SportIdent station as that&#39;s a limitation of the technology.</p><h2 id="ok-but-not-downloaded-provisional-ok" tabindex="-1">&quot;OK&quot; but not downloaded (provisional OK) <a class="header-anchor" href="#ok-but-not-downloaded-provisional-ok" aria-label="Permalink to &quot;&quot;OK&quot; but not downloaded (provisional OK)&quot;">​</a></h2><p>When a competitor gets a <strong>radio finish punch</strong> but hasn&#39;t yet downloaded their card, Manager marks them <strong>OK</strong> but flags the result as <strong>provisional</strong>. In the UI this shows as <strong><code>OK*</code></strong> — an orange-outlined chip, and on results/leaderboards the time carries a <code>*</code> and is shown in italics with no medal.</p><p>For the safety check, <strong>provisional OK counts as &quot;accounted for&quot;</strong> — a finish punch means the person is back from their course. But it is <em>not</em> a finished result yet:</p><ul><li>A provisional time is <strong>never</strong> published as a result. An exported or uploaded results file (IOF XML, Eventor) still lists the competitor, but with the status overridden to <strong>DNF</strong> and no time — the card hasn&#39;t been read, so nothing confirms they completed the course. See <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</li><li>The provisional <strong>OK</strong> is replaced by the real result when the card is downloaded — which may turn out to be <strong>OK</strong>, <strong>MP</strong> or <strong>DNF</strong>.</li></ul><p>So <code>OK*</code> people are safe but unfinished business: chase them to the download tent so you get a real result. You can list them quickly — the <strong>Status</strong> filter on the <a href="#where-to-see-who-is-still-out">competitor list</a> has a dedicated &quot;OK (not downloaded)&quot; option that sits right next to <strong>OK</strong>.</p><h2 id="reading-sportident-stations" tabindex="-1">Reading SportIdent stations <a class="header-anchor" href="#reading-sportident-stations" aria-label="Permalink to &quot;Reading SportIdent stations&quot;">​</a></h2><p>When radios let you down — a finish radio missed people, a control stopped reporting, or you simply want to <em>prove</em> who came through somewhere — read the station&#39;s own internal memory using <strong>Station Memory</strong>. Every control unit keeps a backup of every <em>manual</em> punch.</p><p>This is the authoritative safety net for the &quot;is everyone back?&quot; question:</p><ul><li><strong>Finish station</strong> — reading the finish unit&#39;s backup tells you exactly which cards manually punched the finish. Anyone in the finish backup is out of the forest.</li><li><strong>Start station</strong> — reading the start unit&#39;s backup tells you who actually <em>started</em>. Cross-reference against your <strong>On Course</strong> list: a name that&#39;s On Course but absent from the start backup probably never started (a no-show), not a missing runner.</li><li><strong>Check station</strong> — the check unit catches people who checked in near the start; useful corroboration that someone was present and heading out and very useful for allocated starts.</li></ul><p>The <strong>Station Memory</strong> view auto-detects the station&#39;s mode and labels it (<strong>START</strong> / <strong>CHECK</strong> / <strong>FINISH</strong>, or the resolved control name for ordinary controls). Recovered punches that duplicate radio punches Manager already has are reconciled rather than double-counted. See <a href="./station-memory">Station Memory</a> for the full read-out procedure and hardware notes.</p><h4 id="applying-station-records-also-changes-status" tabindex="-1">Applying station records also changes status <a class="header-anchor" href="#applying-station-records-also-changes-status" aria-label="Permalink to &quot;Applying station records also changes status&quot;">​</a></h4><p>Reading a station&#39;s memory is not just informational — when you <strong>apply</strong> the recovered records (select them and confirm), Manager records each as an independent <em>station download</em> on the matching competitor <strong>and updates their status</strong>, which directly moves people in and out of the <strong>On Course</strong> count:</p><ul><li><strong>Start or Check station → puts a competitor On Course.</strong> A competitor who hadn&#39;t started yet (status <em>None</em>) is promoted to <strong>On Course</strong> — the punch is proof they went out. Someone already On Course or already finished keeps their status, and the start/check download never overrides an allocated start time or race time.</li><li><strong>Finish station → takes a competitor off course.</strong> An <em>On Course</em> competitor is marked <strong>DNF (Did Not Finish)</strong> — they came back, so they&#39;re accounted for and drop out of the <strong>On Course</strong> count, but a finish-station read alone gives no verified result (there are no splits to check). To turn that into a real result, download their card. A competitor who never started (<em>None</em>) is left alone — a stray finish punch won&#39;t DNF a non-starter — and anyone with a final result already (a real OK/MP/etc.) is unchanged.</li></ul><p>A few practical points:</p><ul><li>Applying is <strong>idempotent</strong> — a record already recorded on a competitor is skipped, so you can safely re-read and re-apply a station.</li><li>For <strong>unmatched cards</strong> (no competitor has that card number), a Start or Check read can create an <em>Unknown</em> On-Course competitor on the spot; unmatched <strong>Finish</strong> cards are listed for information only and are never auto-created (an unknown finisher carries no lost-in-forest risk to chase).</li><li>This is exactly why the finish station is the strongest tool for clearing the <strong>On Course</strong> list at the end of the day: reading it sweeps everyone who came back but missed their finish punch into DNF, leaving only the people genuinely unaccounted for.</li></ul><h2 id="course-closure-settling-the-list-at-a-set-time" tabindex="-1">Course closure: settling the list at a set time <a class="header-anchor" href="#course-closure-settling-the-list-at-a-set-time" aria-label="Permalink to &quot;Course closure: settling the list at a set time&quot;">​</a></h2><p>Most events declare a <strong>course closure</strong> — the time of day everyone has to be back — and Manager can act on it. Set it in <strong>Edit event → Details → Course closure</strong> (it is off unless you set it).</p><p>When that time of day arrives, Manager settles the entries nobody has accounted for, so the event stops claiming results it cannot produce:</p><table tabindex="0"><thead><tr><th>Where they were</th><th>Where course closure puts them</th></tr></thead><tbody><tr><td><strong>On Course</strong></td><td><strong>Overtime</strong> — they went out and are not back</td></tr><tr><td><strong>On Course</strong>, still waiting in a relay changeover pen</td><td><strong>DNS</strong> — they were never handed the map, so they never started</td></tr><tr><td>No status at all</td><td><strong>DNS</strong> — nobody started them and the course is shut</td></tr><tr><td>Provisional <strong><code>OK*</code></strong> (radio finish, card not read)</td><td><strong>DNF</strong>, keeping the time and the <code>*</code> — the card is still to be read</td></tr></tbody></table><p>It also scores a <strong>card downloaded afterwards</strong> as <strong>Overtime</strong> rather than <strong>OK</strong>, when the card&#39;s <em>finish punch</em> was at or after the closure — the runner got round, just not by the time you set. Only a clean OK is affected; a mis-punch stays <strong>MP</strong>. Both this and the sweep above are worked out rather than stored, so fixing a mis-typed closure time re-scores everybody, and you can set any competitor back to <strong>OK</strong> by hand and have it stick.</p><p>Two things it deliberately does <strong>not</strong> do, and they are the ones that matter for safety:</p><ul><li><strong>It does not decide anyone is accounted for.</strong> A runner marked <strong>Overtime</strong> with no time and no finish behind them is still on the <strong>On Course</strong> list, still in the dashboard&#39;s On course count, and still in the class list&#39;s column — because nobody has seen them. The status changed; the safety picture did not. <strong>This is true of an Overtime you set by hand as well:</strong> marking a late runner Overtime is a call about their result, not a report that they are back. They leave those lists when something says they are: a race time, a radio finish punch, a downloaded card, or a finish read out of the <a href="#reading-sportident-stations">finish station&#39;s memory</a>. Likewise the <code>OK*</code> runners the closure moved to <strong>DNF</strong> stay on the <strong>Pending</strong> list and the download tent&#39;s screen until their card is read.</li><li><strong>It does not overrule you.</strong> Any status you set by hand is yours, and course closure — the sweep and the download rule alike — leaves it alone.</li></ul><p>So course closure does not replace the safety pass below; it does the bookkeeping half of it — the no-shows, the un-downloaded finishers and the late results — and leaves you the names that need a person to answer for them.</p><h2 id="where-to-see-who-is-still-out" tabindex="-1">Where to see who is still out <a class="header-anchor" href="#where-to-see-who-is-still-out" aria-label="Permalink to &quot;Where to see who is still out&quot;">​</a></h2><p>Manager surfaces the <strong>On Course</strong> picture in several places. The two below are the ones the safety check itself is run from; every other place it shows up — the competitor and class lists, the Results view, the public screens, the download tent&#39;s own info screen — is collected in <strong><a href="./who-is-still-on-course">Seeing who is still on course</a></strong>.</p><h3 id="the-dashboard-competitors-tile" tabindex="-1">The dashboard Competitors tile <a class="header-anchor" href="#the-dashboard-competitors-tile" aria-label="Permalink to &quot;The dashboard Competitors tile&quot;">​</a></h3><p>The <strong>Competitors</strong> tile on the <a href="./dashboard">event dashboard</a> shows the running totals — <strong>Total</strong>, <strong>Started</strong>, <strong>On Course</strong>, <strong>Pending</strong> and <strong>Finished</strong> — plus a graph of how many people have been On Course over the course of the day. The <strong>On Course</strong> figure is the headline safety number, highlighted in orange; it and <strong>Pending</strong> are drawn as buttons, because clicking them opens the list behind each.</p><p><img src="'+t+'" alt="The dashboard Competitors tile: Total 148, Started 104, On Course 5 and Pending 3 drawn as raised buttons, Finished 99, above a graph of how many competitors were on course over the day."></p><p>It includes both:</p><ul><li>competitors whose status is <strong>On Course</strong>, and</li><li><strong>unknown cards</strong> — radio activity from a card not matched to any competitor, where no finish punch has been seen. These represent someone out there you can&#39;t even name, so they&#39;re counted too.</li></ul><h3 id="the-on-course-dialog-click-the-tile" tabindex="-1">The &quot;On Course&quot; dialog (click the tile) <a class="header-anchor" href="#the-on-course-dialog-click-the-tile" aria-label="Permalink to &quot;The &quot;On Course&quot; dialog (click the tile)&quot;">​</a></h3><p>When the <strong>On Course</strong> count is above zero, the number becomes <strong>clickable</strong>. Clicking it opens the <strong>On Course</strong> dialog — the single most useful screen for the safety check. It lists everyone still out, with:</p><ul><li><strong>Name</strong> — click it to jump straight to that competitor&#39;s information. Unknown cards show as an italic <em>Unknown</em>.</li><li><strong>Card number</strong> — their card number.</li><li><strong>Class</strong> and <strong>Start</strong> time.</li><li><strong>Last Seen</strong> — the last radio control they punched and when (e.g. <code>31 @ 11:03:18</code>), <code>START</code> where they have punched nothing since starting, or <code>-</code> if no radio punch has ever been seen for them. The chip shows the control&#39;s code, or the radio&#39;s name if you gave it one.</li></ul><p><img src="'+o+'" alt="The On Course dialog listing five competitors still out, each showing name, SI card number, class, start time and a Last Seen control with time — controls 31, 32 and 33, and one row reading START. The last row is an unknown card."></p><p>Read the <strong>Last Seen</strong> column in the example above and the list sorts itself into jobs. Jordan Blake punched control <strong>31</strong> at 11:03 and has not been seen since, which is why he is at the top even though three people started after him — the sort is on when somebody was last seen, not on when they started. Sam Carter shows <strong>START</strong>: he punched the start and no control since, which is the least Manager can know about somebody who is out there. The bottom row is an <em>Unknown</em> card (SI 8663331) that is out on the course but isn&#39;t matched to any competitor.</p><p>The list is sorted so the people <strong>seen longest ago (or never)</strong> are at the <strong>top</strong> — i.e. the most concerning names surface first. Unknown cards appear as <em>Unknown</em> rows with whatever start/last-seen radio activity they have.</p><p>Each row also has a <strong>delete radio punches</strong> action (the trash icon). Use this only to remove genuinely spurious punches — for example a phantom or mis-read punch that&#39;s keeping a card showing as still-out. Deleting punches is permanent and re-evaluates the affected competitor from their remaining punches.</p><h3 id="everywhere-else" tabindex="-1">Everywhere else <a class="header-anchor" href="#everywhere-else" aria-label="Permalink to &quot;Everywhere else&quot;">​</a></h3><p>The <strong>Competitors</strong> page&#39;s <strong>Status</strong> filter (which offers both <strong>On Course</strong> and the <strong>OK (not downloaded)</strong> option described <a href="#ok-but-not-downloaded-provisional-ok">above</a>), the <strong>Classes</strong> page&#39;s per-class <strong>On Course</strong> column (whose count opens this same dialog for that class), the Results view, the public screens and the download tent&#39;s <strong>Pending downloads</strong> screen all show a slice of the same picture. They are covered, with screenshots, in <a href="./who-is-still-on-course">Seeing who is still on course</a>.</p><h2 id="marking-people-on-course-or-not" tabindex="-1">Marking people on course or not <a class="header-anchor" href="#marking-people-on-course-or-not" aria-label="Permalink to &quot;Marking people on course or not&quot;">​</a></h2><p>Sometimes the automatic picture is wrong and you need to set it by hand.</p><h3 id="manually-setting-a-competitor-s-status" tabindex="-1">Manually setting a competitor&#39;s status <a class="header-anchor" href="#manually-setting-a-competitor-s-status" aria-label="Permalink to &quot;Manually setting a competitor&#39;s status&quot;">​</a></h3><p>Open a competitor (from any list, or from the <strong>On Course</strong> dialog) to reach the <strong>Edit Competitor</strong> dialog, then use the <strong>Status</strong> dropdown. You can set <strong>On Course</strong> directly (to mark someone as out when Manager didn&#39;t catch it), or move them off the course by setting a finished status (<strong>OK</strong>, <strong>MP</strong>, <strong>DNF</strong>, <strong>DSQ</strong>, <strong>OOC</strong>, <strong>Overtime</strong>) or <strong>DNS</strong>.</p><p>A couple of rules the dialog enforces:</p><ul><li>You <strong>can&#39;t set OK</strong> unless the competitor has a running time (an existing result, or one you enter). There&#39;s nothing to rank otherwise.</li><li><strong>Resetting to <em>None</em> (&quot;no result at all&quot;) is restricted.</strong> Manager only lets you clear a competitor back to <em>None</em> when there&#39;s <strong>no evidence they started or finished</strong> — no race time, no provisional radio result, no punched start, no Start/Check/Finish station read, no assigned card download, and no timed radio control visits. (An allocated start time alone doesn&#39;t count as evidence — that&#39;s the no-show case.) If real evidence exists, the dialog blocks the change and shows a <strong>&quot;Can&#39;t set status to None&quot;</strong> dialog listing the specific evidence (e.g. <em>&quot;a recorded race time (00:45:30)&quot;</em>, <em>&quot;a downloaded card&quot;</em>, <em>&quot;2 radio punches&quot;</em>). This guard exists so a genuine result is never quietly discarded by relabelling.</li></ul><h3 id="marking-no-shows-as-dns-bulk" tabindex="-1">Marking no-shows as DNS (bulk) <a class="header-anchor" href="#marking-no-shows-as-dns-bulk" aria-label="Permalink to &quot;Marking no-shows as DNS (bulk)&quot;">​</a></h3><p>The most common end-of-event correction is clearing out the no-shows that the auto-start timer flagged as <strong>On Course</strong>. Rather than editing each one, open the competitor list&#39;s <strong>Actions</strong> menu and choose <strong>Set competitors DNS</strong>. It lets you select classes and a status filter of <strong>None</strong> and/or <strong>On Course (no radio punches)</strong>. When you include <strong>On Course</strong>, Manager <em>only</em> sweeps up people with <strong>no actual radio control visit times</strong> — so you can&#39;t accidentally DNS someone who genuinely started and was seen by a radio. That&#39;s exactly the set of &quot;had a start time, never actually turned up&quot; no-shows you want to clear.</p><p><img src="'+i+'" alt="The Set Competitors DNS dialog: status checkboxes (None ticked, On Course unticked), a list of classes each with a count of matching competitors, and a total of how many will be set to Did Not Start."></p><p>Each class shows how many competitors currently match, and the dialog totals how many will be set to <strong>Did Not Start</strong> before you confirm. Do this only once you&#39;re confident those people really didn&#39;t start — that&#39;s the judgement call Manager can&#39;t make for you.</p><h3 id="phantom-radio-punches-keeping-someone-on-course" tabindex="-1">Phantom radio punches keeping someone &quot;on course&quot; <a class="header-anchor" href="#phantom-radio-punches-keeping-someone-on-course" aria-label="Permalink to &quot;Phantom radio punches keeping someone &quot;on course&quot;&quot;">​</a></h3><p>If a stray or duplicated radio punch is wrongly holding a competitor (or unknown card) in the <strong>On Course</strong> bucket, you can suppress it. The <strong>Radio Times</strong> chips on the competitor list offer a <strong>suppress</strong> action for On Course competitors (when the event is using meshO Prime for radio punches); suppressing hides that punch from the Leaderboard and recalculates the competitor&#39;s predicted position without it. For an outright bad punch, the <strong>On Course</strong> dialog&#39;s per-row delete removes the radio punches entirely. See <a href="./radio-punches">Radio punches</a> and <a href="./resolving-issues">Resolving issues on the day</a> for the detail.</p><h2 id="a-worked-end-of-event-safety-pass" tabindex="-1">A worked end-of-event safety pass <a class="header-anchor" href="#a-worked-end-of-event-safety-pass" aria-label="Permalink to &quot;A worked end-of-event safety pass&quot;">​</a></h2><p>Putting it together, once the last expected competitor should be home:</p><ol><li><strong>Dashboard → Competitors tile.</strong> Note the <strong>On Course</strong> count. If zero, you&#39;re done — confirm with the organisers and move on. (If you set a <a href="#course-closure-settling-the-list-at-a-set-time">course closure</a>, the no-shows have already been marked DNS for you — but everyone the count still holds is a name you have to answer for, whether Manager calls them On Course or Overtime.)</li><li><strong>Click On Course</strong> to open the dialog. Work top-down (longest-unseen first).</li><li>For each name, decide: <ul><li><strong>Genuinely still out</strong> → tell the organisers; this is the real safety case.</li><li><strong>Finished but no result</strong> (showing <code>OK*</code>, or you know they came in) → download their card, or read the <a href="#reading-sportident-stations">finish station memory</a> to confirm, or set the status by hand.</li><li><strong>Never started</strong> (no radio activity, not in the start station backup) → mark <strong>DNS</strong>, individually or via the bulk <strong>Set DNS</strong> dialog.</li></ul></li><li><strong>Re-read start/finish stations</strong> to confirm the list against hardware truth, noting that beacon punches aren&#39;t recorded by stations.</li><li><strong>Recheck the On Course count is zero</strong> (and there are no leftover <em>Unknown</em> cards) before declaring everyone is back.</li></ol><p>Then continue with the rest of the <a href="./../after-the-event/end-of-event-checklist">end-of-event checklist</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./who-is-still-on-course">Seeing who is still on course</a></li><li><a href="./dashboard">The event dashboard</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./radio-punches">Radio punches</a></li><li><a href="./station-memory">Station Memory</a></li><li><a href="./../reference/status-and-race-time">Status and race time rules</a></li><li><a href="./resolving-issues">Resolving issues on the day</a></li><li><a href="./../after-the-event/end-of-event-checklist">End-of-event checklist</a></li></ul>',82)])])}const w=n(h,[["render",l]]);export{y as __pageData,w as default};
